package com.novasoft.psicoapp.config;
import com.novasoft.psicoapp.repo.UserRepo; import com.novasoft.psicoapp.service.JwtService; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.context.annotation.*; import org.springframework.security.authentication.*; import org.springframework.security.config.annotation.method.configuration.*; import org.springframework.security.config.annotation.web.builders.*; import org.springframework.security.config.http.*; import org.springframework.security.core.authority.*; import org.springframework.security.core.context.*; import org.springframework.security.core.userdetails.*; import org.springframework.security.crypto.bcrypt.*; import org.springframework.security.crypto.password.*; import org.springframework.security.web.*; import org.springframework.security.web.authentication.*; import org.springframework.stereotype.*; import org.springframework.web.filter.*; import java.io.*; import java.util.*;
@Configuration @EnableMethodSecurity public class SecurityConfig{
 @Bean public PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
 @Bean public SecurityFilterChain chain(HttpSecurity http, JwtFilter jwt) throws Exception{return http.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/","/index.html","/app.js","/style.css","/api/auth/**").permitAll().anyRequest().authenticated()).addFilterBefore(jwt, UsernamePasswordAuthenticationFilter.class).build();}
 @Bean public UserDetailsService uds(UserRepo repo){return username->repo.findByEmail(username).map(u->{List<SimpleGrantedAuthority> roles=new ArrayList<>(); roles.add(new SimpleGrantedAuthority("ROLE_"+u.role.name())); if(u.role.name().equals("ADMIN")){roles.add(new SimpleGrantedAuthority("ROLE_PROFESOR")); roles.add(new SimpleGrantedAuthority("ROLE_ESTUDIANTE"));} return new org.springframework.security.core.userdetails.User(u.email,u.password,roles);}).orElseThrow(()->new UsernameNotFoundException("Usuario no encontrado"));}
}
@Component class JwtFilter extends OncePerRequestFilter{ private final JwtService jwt; private final UserDetailsService uds; JwtFilter(JwtService j,UserDetailsService u){jwt=j;uds=u;} protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer ")){try{String email=jwt.subject(h.substring(7)); UserDetails d=uds.loadUserByUsername(email); SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(d,null,d.getAuthorities()));}catch(Exception ignored){}} chain.doFilter(req,res);} }
